import{c as e,Q as a,j as i,m as l}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"BOOTH Package Linker","text":"BOOTH 購入アイテムをまとめて管理","tagline":"ダウンロード・整理・検索・新着通知を 1 つの Windows デスクトップアプリで","actions":[{"theme":"brand","text":"インストール","link":"/guide/installation"},{"theme":"alt","text":"ガイドを読む","link":"/guide/library"},{"theme":"alt","text":"GitHub","link":"https://github.com/ChanyaVRC/booth-package-linker-releases"}]},"features":[{"icon":"📥","title":"ライブラリ一括取得","details":"BOOTH の購入・ギフト・無料ダウンロードをまとめて取得。ZIP は既定で自動展開し、設定で ZIP のまま保存することもできます。"},{"icon":"🔗","title":"ブラウザから直接ダウンロード","details":"ブラウザの BOOTH ページから専用リンクで 1 クリック直送。既定では受信後にダウンロードを開始し、設定で登録だけにもできます。"},{"icon":"🏪","title":"ショップ別表示","details":"購入アイテムをショップ単位で一覧。BOOTH のフォロー中ショップを自動取り込みし、新作が出ると通知ベルで知らせます。"},{"icon":"🔖","title":"スキリスト連携","details":"BOOTH のスキリストをそのままアプリ側にも反映。購入済みかどうかもバッジで確認できます。"},{"icon":"🔁","title":"ストレージ最適化","details":"同じ中身のファイル・フォルダや旧バージョンを安全に整理。完全一致は 1 件を保持し、旧版は確認してから削除できます。"},{"icon":"📦","title":"Unity プロジェクトに直接取り込み","details":"起動中の Unity プロジェクトに .unitypackage を直接取り込み。Unity 拡張のインストールは不要。複数のプロジェクトを開いていれば、取り込み先を選べます。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786265066000}'),n={name:"index.md"};function r(o,t,s,d,h,c){return a(),i("div",null,[...t[0]||(t[0]=[l('<h2 id="どんなソフト" tabindex="-1">どんなソフト？ <a class="header-anchor" href="#どんなソフト" aria-label="Permalink to &quot;どんなソフト？&quot;">​</a></h2><p><strong>BOOTH Package Linker</strong> は <a href="https://booth.pm/" target="_blank" rel="noreferrer">BOOTH</a> で買った VRChat / Unity 向けアセットを 1 つの Windows デスクトップアプリで管理するためのツールです。</p><p>主にこういう使い方を想定しています:</p><ul><li>BOOTH で買ったものを <strong>一括ダウンロード</strong> して 1 つのフォルダに整理する</li><li>ブラウザの BOOTH ページから専用リンクで追加し、設定に応じて <strong>そのままダウンロード</strong></li><li>過去に買ったアイテムを <strong>検索 / 絞り込み / カスタムカテゴリ付け</strong> して再発見しやすくする</li><li><strong>完全重複や旧バージョン</strong> を見つけてディスクを掃除する</li><li>フォロー中ショップの <strong>新作</strong> に気付く</li></ul><h2 id="公式ツールではない" tabindex="-1">公式ツールではない <a class="header-anchor" href="#公式ツールではない" aria-label="Permalink to &quot;公式ツールではない&quot;">​</a></h2><p>このアプリは BOOTH (pixiv 株式会社) の公式ツールではありません。 BOOTH 側の仕様変更で動かなくなる可能性があります。</p><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><ul><li>初めて使う方は <a href="/guide/installation">インストール</a> から</li><li>画面ごとの使い方は <a href="/guide/library">ライブラリ画面</a> など各ページを参照</li><li>キー操作は <a href="/guide/keyboard-shortcuts">キーボードショートカット</a> にまとめてあります</li></ul>',8)])])}const O=e(n,[["render",r]]);export{g as __pageData,O as default};
